import{R as e,e as o,f as n,U as r}from"./chunks/framework.ywem4qy5.js";const u=JSON.parse('{"title":"Pardot","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/pardot.md","filePath":"integrations/crm/pardot.md","lastUpdated":1775908585000}'),i={name:"integrations/crm/pardot.md"};function s(l,t,a,g,c,h){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="pardot" tabindex="-1">Pardot <a class="header-anchor" href="#pardot" aria-label="Permalink to &quot;Pardot&quot;">​</a></h1><p>Follow the below steps to connect to the Pardot API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Pardot as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-pardot-api" tabindex="-1">Step 2. Connect to the Pardot API <a class="header-anchor" href="#step-2-connect-to-the-pardot-api" aria-label="Permalink to &quot;Step 2. Connect to the Pardot API&quot;">​</a></h3><ol><li>Go to <a href="https://www.salesforce.com" target="_blank">Pardot</a> and login to your account.</li><li>In the main menu, on the top-right, click the <strong>Settings</strong> icon and select <strong>Setup</strong>.</li><li>In the left-hand sidebar, click on <strong>Apps</strong> → <strong>App Manager</strong>.</li><li>Click the <strong>New Connected App</strong> button.</li><li>Fill out all required fields.</li><li>In the <strong>API (Enable OAuth Settings)</strong> section, tick the <strong>Enable OAuth Settings</strong> checkbox. <ul><li>In the <strong>Callback URL</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>In the <strong>Selected OAuth Scopes</strong> field, select the following permissions from the list and click <strong>Add</strong> arrow button: <ul><li><strong>Manage Pardot services (pardot_api)</strong>.</li><li><strong>Perform requests on your behalf at any time (refresh_token, offline_access)</strong>.</li></ul></li><li>Untick <strong>Require Proof Key for Code Exchange (PKCE) Extension for Supported Authorization Flows</strong>.</li><li>Tick <strong>Require Secret for Web Server Flow</strong>.</li><li>Untick <strong>Require Secret for Refresh Token Flow</strong>.</li></ul></li><li>Click the <strong>Save</strong> button.</li><li>Copy the <strong>Consumer Key</strong> from Pardot and paste in the <strong>Consumer Key</strong> field in Formie.</li><li>Copy the <strong>Consumer Secret</strong> from Pardot and paste in the <strong>Consumer Secret</strong> field in Formie.</li><li>Click on the <strong>Manage</strong> button.</li><li>Click on the <strong>Edit Policies</strong> button.</li><li>In the <strong>OAuth policies</strong> section: <ul><li>In the <strong>Permitted Users</strong> field, select <strong>All users may self-authorize</strong>.</li><li>In the <strong>IP Relaxation</strong> field, select <strong>Relaxed IP restrictions</strong>.</li></ul></li><li>Click the <strong>Save</strong> button.</li><li>In the main menu, on the top-right, click the <strong>Settings</strong> icon and select <strong>Setup</strong>.</li><li>Enter <strong>Business Unit</strong> in the Quick Find box, and click on <strong>Business Unit Setup</strong>.</li><li>Copy the <strong>Business Unit ID</strong> from Pardot and paste in the <strong>Business Unit ID</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Pardot, where you must approve Formie to access your Pardot account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const p=e(i,[["render",s]]);export{u as __pageData,p as default};
